/**
 * Every endpoint the UI calls must exist in the backend's OpenAPI document
 * (lib/api/schema.d.ts, generated by `npm run gen:api`). Guards against the
 * frontend inventing or drifting from backend capabilities.
 */
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { describe, expect, it } from "vitest";

const norm = (p: string) => p.replace(/\$\{[^}]+\}|\{[^}]+\}/g, "{}");
const schema = readFileSync(resolve(process.cwd(), "lib/api/schema.d.ts"), "utf8");
const endpoints = readFileSync(resolve(process.cwd(), "lib/api/endpoints.ts"), "utf8");

function operations(): Set<string> {
  const out = new Set<string>();
  const pathsBlock = schema.slice(schema.indexOf("export interface paths"), schema.indexOf("export type webhooks"));
  const re = /^ {4}"(\/[^"]*)": \{([\s\S]*?)^ {4}\};/gm;
  for (const m of pathsBlock.matchAll(re)) {
    for (const verb of ["get", "post", "patch", "delete", "put"]) {
      if (new RegExp(`^ {8}${verb}: operations`, "m").test(m[2]!)) out.add(`${verb.toUpperCase()} ${norm(m[1]!)}`);
    }
  }
  return out;
}

describe("API contract", () => {
  it("calls only operations the backend defines", () => {
    const ops = operations();
    expect(ops.size).toBeGreaterThan(30);
    const calls = [...endpoints.matchAll(/apiRequest<[^>]*>\(\s*[`"]([^`"]+)[`"](?:,\s*\{([^}]*))?/g)].map((m) => {
      const method = /method:\s*"(\w+)"/.exec(m[2] ?? "")?.[1] ?? "GET";
      return `${method} ${norm(m[1]!)}`;
    });
    expect(calls.length).toBeGreaterThan(30);
    expect(calls.filter((c) => !ops.has(c))).toEqual([]);
  });
});
